def lcs(s1: list, s2: list) -> int:
    m, n = len(s1), len(s2)
    counter = [[0] * (n + 1) for i in range(m + 1)]
    longest, x_longest = 0, 0
    for x in range(m):
        for y in range(n):
            if s1[x] == s2[y]:
                c = counter[x][y] + 1
            else:
                c = 0
            counter[x + 1][y + 1] = max(c, counter[x + 1][y], counter[x][y + 1])
            if counter[x + 1][y + 1] > longest:
                longest = counter[x + 1][y + 1]
                x_longest = x + 1
    return longest

s1 = tokenize(reference)
s2 = tokenize(continuation)
