class OptimizeDnsContext:
    def __init__(self, enable: bool):
        self.enable = enable
        self.context = dns.context.ResolverConf(
            {
                "options": ["single-request-reopen=no"],
                "ndots": 1,
                "rotate": True,
                "timeout": 5,
                "lifetime": 5,
            }
        )

    def __enter__(self):
        if self.enable:
            dns.resolver.default_resolver = dns.resolver.Resolver(configure=False)
            dns.resolver.default_resolver.nameservers = ["8.8.8.8"]
            dns.resolver.default_resolver.cache = dns.resolver.LRUCache()
            dns.resolver.default_resolver.retry_servfail = True
            dns.resolver.default_resolver.cache.flush()
            dns.resolver.default_resolver.context = self.context
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        if self.enable:
            dns.resolver.default_resolver = dns.resolver.Resolver(configure=False)
            dns.resolver.default_resolver.nameservers = []
            dns.resolver.default_resolver.cache = None
            dns.resolver.default_resolver.retry_servfail = False
            dns.resolver.default_resolver.context = None

return OptimizeDnsContext(enable)

