@contextlib.contextmanager
def profile_flops(model):
    flops = defaultdict(int)
    with profile(activities=[ProfilerActivity.CPU], record_shapes=True) as prof:
        yield flops
    # print(prof.key_averages().table(sort_by="cpu_time_total", row_limit=30))
    for j in range(len(prof.function_events)):
        flops[prof.function_events[j].name] += prof.function_events[j].cpu_time

def compute_flops(model, inputs):
    with profile_flops(model) as prof:
        model(inputs)
    return prof

